//! Dart for the app, over `universal_ble`.
//!
//! The generated file is a typed client for one schema: a class per proto
//! service, with a method or a stream for each characteristic and only the
//! properties the schema declares — `Stream<SyncMessage> get messagesUpdates` for
//! a `NOTIFY` characteristic, `Future<void> writeRequests(SyncRequest)` for a
//! written one, `Future<DeviceInfo> readInfo()` for a readable one.
//!
//! It reaches BLE through one narrow interface it declares itself
//! (`GattClientLink` in the output), so an app implements it over `universal_ble`
//! in a few lines and a test implements it without a radio. Everything above that
//! interface — which UUID carries what, which way each message travels, how a bare
//! value is encoded — comes from the schema.
//!
//! `universal_ble`'s own API is deliberately not called directly: a target is the
//! schema plus a link, which is what keeps the generated client testable and the
//! plugin swappable.

use std::collections::BTreeSet;
use std::fmt::Write;

use crate::error::Error;
use crate::generator::Output;
use crate::model::{Bare, Characteristic, Gatt, Prop, Service, ValueType};

/// The name the command line uses.
pub const NAME: &str = "dart-universal-ble";

/// The file this target writes.
pub const OUTPUT_FILE: &str = "gatt_client.dart";

/// What the generated Dart needs to know about the crate it lands in.
#[derive(Debug, Clone)]
pub struct Config {
    /// The import the generated protobuf classes arrive through, written as Dart
    /// writes it, e.g. `../protocol/calypso.pb.dart`.
    pub messages_import: String,
    /// The prefix those classes are imported under, e.g. `pb`.
    pub messages_prefix: String,
    /// Backing buffer of a pipe characteristic: the largest chunk that goes in
    /// one notification.
    pub pipe_chunk_max: usize,
    /// Largest message a pipe may carry.
    pub pipe_msg_max: usize,
    /// Chunks a pipe may have in flight before it waits for an acknowledgement.
    pub window: u8,
    /// No-progress timeout for one pipe transfer, in milliseconds.
    pub xfer_timeout_ms: u32,
    /// The command that regenerates this file, written into its own header.
    pub regenerate_with: Option<String>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            messages_import: "messages.pb.dart".to_string(),
            messages_prefix: "pb".to_string(),
            pipe_chunk_max: 244,
            pipe_msg_max: 0,
            window: 8,
            xfer_timeout_ms: 5000,
            regenerate_with: None,
        }
    }
}

/// The interface the generated clients reach BLE through.
const LINK: &str = "GattClientLink";

/// Generate the typed client for `gatt`.
pub fn generate(gatt: &Gatt, config: &Config) -> Result<Output, Error> {
    let mut out = String::new();
    let version = env!("CARGO_PKG_VERSION");

    let _ = writeln!(
        out,
        "// GENERATED FILE -- DO NOT EDIT.\n\
         //\n\
         // {}\n\
         //\n\
         // Generated by gatt-gen {version} from the schema.{}",
        summary(gatt),
        match &config.regenerate_with {
            Some(command) => format!(" Regenerate with `{command}`."),
            None => String::new(),
        },
    );

    let needs = Needs::of(gatt);
    out.push('\n');
    if needs.utf8 {
        out.push_str("import 'dart:convert';\n");
    }
    out.push_str("import 'dart:typed_data';\n");
    let _ = writeln!(
        out,
        "\nimport '{}' as {};",
        config.messages_import, config.messages_prefix
    );

    emit_link(&mut out, &needs);
    emit_bare_codecs(&mut out, &needs);

    for service in &gatt.services {
        emit_client(&mut out, service, config);
    }
    emit_pipes(&mut out, gatt, config);

    while out.ends_with("\n\n") {
        out.pop();
    }

    Ok(Output {
        file_name: OUTPUT_FILE.to_string(),
        source: out,
    })
}

/// What the schema asks the generated file to be able to do, so that it declares
/// only what it uses: an interface method nobody calls is one every
/// implementation has to stub.
#[derive(Default)]
struct Needs {
    subscribe: bool,
    values: bool,
    write: bool,
    read: bool,
    /// The bare kinds a codec helper is needed for.
    bare: BTreeSet<Bare>,
    utf8: bool,
}

impl Needs {
    fn of(gatt: &Gatt) -> Self {
        let mut needs = Needs::default();
        for characteristic in gatt.characteristics() {
            let subscribable = characteristic.is_subscribable();
            needs.subscribe |= subscribable;
            needs.values |= subscribable;
            needs.write |= characteristic.is_written();
            needs.read |= characteristic.props.contains(&Prop::Read);
            if let ValueType::Bare(bare) = characteristic.value_type() {
                needs.bare.insert(*bare);
                needs.utf8 |= *bare == Bare::Utf8;
            }
        }
        needs
    }
}

fn summary(gatt: &Gatt) -> String {
    let services: Vec<String> = gatt
        .services
        .iter()
        .map(|service| format!("{} ({})", service.short_name(), service.uuid))
        .collect();
    format!("Schema: {}", services.join(", "))
}

/// The narrow interface the client needs, and nothing else.
fn emit_link(out: &mut String, needs: &Needs) {
    let _ = writeln!(
        out,
        "\n/// The raw BLE operations a generated client needs.\n\
         ///\n\
         /// `universal_ble` is one implementation of this (a few lines over its static\n\
         /// API); a test's fake is another, which is what lets a client generated from a\n\
         /// schema be exercised without a radio.\n\
         abstract class {LINK} {{"
    );
    if needs.subscribe {
        let _ = writeln!(
            out,
            "  /// Subscribe to a characteristic, completing once notifications flow.\n\
             \x20 Future<void> subscribe(String serviceUuid, String characteristicUuid);"
        );
    }
    if needs.values {
        let _ = writeln!(
            out,
            "\n  /// The values arriving on a characteristic, in the order they arrive.\n\
             \x20 Stream<Uint8List> values(String characteristicUuid);"
        );
    }
    if needs.read {
        let _ = writeln!(
            out,
            "\n  /// Read a characteristic once.\n\
             \x20 Future<Uint8List> read(String serviceUuid, String characteristicUuid);"
        );
    }
    if needs.write {
        let _ = writeln!(
            out,
            "\n  /// Write a characteristic.\n\
             \x20 ///\n\
             \x20 /// `withResponse` is the write that reports failure, so it is the default;\n\
             \x20 /// a characteristic that offers only write-without-response asks for the\n\
             \x20 /// other (`universal_ble`'s `withoutResponse`).\n\
             \x20 Future<void> write(\n\
             \x20   String serviceUuid,\n\
             \x20   String characteristicUuid,\n\
             \x20   Uint8List value, {{\n\
             \x20   bool withResponse = true,\n\
             \x20 }});"
        );
    }
    out.push_str("}\n");
}

/// Little-endian codecs for the bare kinds the schema uses. A bare value is raw
/// bytes on the wire (so a stock client reads what it expects), which is why the
/// encoding is spelled out here instead of coming from the message classes.
fn emit_bare_codecs(out: &mut String, needs: &Needs) {
    for bare in &needs.bare {
        let Some((width, getter)) = bare_helper(*bare) else {
            continue;
        };
        let name = bare.name();
        let get = format!("get{getter}");
        let set = format!("set{getter}");
        let _ = writeln!(
            out,
            "\n// `gatt.{name}`: {width} raw bytes, little endian.\n\
             Uint8List _encode{name}(int value) {{\n\
             \x20 final data = ByteData({width})..{set}(0, value, Endian.little);\n\
             \x20 return data.buffer.asUint8List();\n\
             }}\n\
             \n\
             int _decode{name}(Uint8List bytes) =>\n\
             \x20   ByteData.sublistView(bytes).{get}(0, Endian.little);"
        );
    }
}

/// The `ByteData` accessor for a bare kind that needs one, and its width.
///
/// The kinds Dart expresses directly — `Uint8List.fromList([value])` for a byte,
/// `utf8` for a string — have none.
fn bare_helper(bare: Bare) -> Option<(usize, &'static str)> {
    match bare {
        Bare::U16 => Some((2, "Uint16")),
        Bare::U32 => Some((4, "Uint32")),
        Bare::I8 => Some((1, "Int8")),
        Bare::I16 => Some((2, "Int16")),
        Bare::I32 => Some((4, "Int32")),
        Bare::F32 => Some((4, "Float32")),
        Bare::U8 | Bare::Bool | Bare::Utf8 | Bare::Bytes => None,
    }
}

/// One client class per service.
fn emit_client(out: &mut String, service: &Service, config: &Config) {
    let class = format!("{}Client", pascal_case(service.short_name()));
    let _ = writeln!(
        out,
        "\n/// `{}`.\n\
         ///\n\
         /// Subscribe before listening, and hold the stream only while the link is up:\n\
         /// these are notifications, not a queue that survives a disconnect.\n\
         class {class} {{\n\
         \x20 {class}(this._link);\n\
         \n\
         \x20 final {LINK} _link;\n\
         \n\
         \x20 /// `{}`.\n\
         \x20 static const String serviceUuid = '{}';",
        service.proto_name, service.proto_name, service.uuid
    );

    for characteristic in &service.characteristics {
        let _ = writeln!(
            out,
            "\n  /// `{}` -- {}, {}.",
            characteristic.path(),
            property_names(characteristic).join("+"),
            characteristic.value_type().describe()
        );
        let _ = writeln!(
            out,
            "  static const String {}Uuid = '{}';",
            lower_camel(&characteristic.name),
            characteristic.uuid
        );
    }

    for characteristic in &service.characteristics {
        if characteristic.pipe.is_none() {
            emit_members(out, characteristic, config);
        }
    }

    out.push_str("}\n");
}

fn emit_members(out: &mut String, characteristic: &Characteristic, config: &Config) {
    let name = lower_camel(&characteristic.name);
    let uuid_field = format!("{name}Uuid");
    let pascal = pascal_case(&characteristic.name);
    let value = dart_type(characteristic, config);
    let description = characteristic.value_type().describe();
    let decode = decode_expression(characteristic, config, "bytes");
    let encode = encode_expression(characteristic, config, "value");

    if characteristic.is_subscribable() {
        // The getter, as one line if `dart format` would keep it as one line and
        // as a broken call chain if it would not: the file is committed and
        // `dart format --set-exit-if-changed` is a gate on it.
        let getter = format!("Stream<{value}> get {name}Updates => ");
        let body = format!("_link.values({uuid_field}).map((bytes) => {decode});");
        let updates = if 2 + getter.len() + body.len() <= MAX_WIDTH {
            body
        } else {
            format!("_link\n      .values({uuid_field})\n      .map((bytes) => {decode});")
        };
        // `_link.subscribe(serviceUuid, levelUuid);` fits on its own line at this
        // indent, so it stays one.
        let _ = writeln!(
            out,
            "\n  /// Subscribe to `{}`. Nothing arrives until this completes.\n\
             \x20 Future<void> subscribe{pascal}() =>\n\
             \x20     _link.subscribe(serviceUuid, {uuid_field});\n\
             \n\
             \x20 /// One `{description}` per notification.\n\
             \x20 {getter}{updates}",
            characteristic.name
        );
    }

    if characteristic.props.contains(&Prop::Read) {
        let _ = writeln!(
            out,
            "\n  /// Read `{}` once.\n\
             \x20 Future<{value}> read{pascal}() async {{\n\
             \x20   final bytes = await _link.read(serviceUuid, {uuid_field});\n\
             \x20   return {decode};\n\
             \x20 }}",
            characteristic.name
        );
    }

    if characteristic.is_written() {
        // A characteristic that offers both is written with a response, because
        // that is the form which reports failure; the device can be asked for the
        // cheaper one by dropping WRITE from its declaration.
        let with_response = characteristic.props.contains(&Prop::Write);
        let _ = writeln!(
            out,
            "\n  /// Write a `{description}`{}.\n\
             \x20 Future<void> write{pascal}({value} value) => _link.write(\n\
             \x20   serviceUuid,\n\
             \x20   {uuid_field},\n\
             \x20   {encode},\n\
             \x20   withResponse: {with_response},\n\
             \x20 );",
            if with_response {
                ""
            } else {
                ", without waiting for a response"
            }
        );
    }
}

/// The Dart type a characteristic's value arrives as.
fn dart_type(characteristic: &Characteristic, config: &Config) -> String {
    match characteristic.value_type() {
        ValueType::Message(message) => {
            format!("{}.{}", config.messages_prefix, short_name(message))
        }
        ValueType::Bare(bare) => match bare {
            Bare::U8 | Bare::U16 | Bare::U32 | Bare::I8 | Bare::I16 | Bare::I32 => {
                "int".to_string()
            }
            Bare::F32 => "double".to_string(),
            Bare::Bool => "bool".to_string(),
            Bare::Utf8 => "String".to_string(),
            Bare::Bytes => "Uint8List".to_string(),
        },
        ValueType::Empty => "void".to_string(),
    }
}

/// Decode `bytes` (a `Uint8List`) into the characteristic's Dart type.
fn decode_expression(characteristic: &Characteristic, config: &Config, bytes: &str) -> String {
    match characteristic.value_type() {
        ValueType::Message(message) => format!(
            "{}.{}.fromBuffer({bytes})",
            config.messages_prefix,
            short_name(message)
        ),
        ValueType::Bare(bare) => match bare {
            Bare::U8 => format!("{bytes}[0]"),
            Bare::Bool => format!("{bytes}.isNotEmpty && {bytes}[0] != 0"),
            Bare::Utf8 => format!("utf8.decode({bytes})"),
            Bare::Bytes => bytes.to_string(),
            other => format!("_decode{}({bytes})", other.name()),
        },
        ValueType::Empty => "()".to_string(),
    }
}

/// Encode `value` (the characteristic's Dart type) into a `Uint8List`.
fn encode_expression(characteristic: &Characteristic, _config: &Config, value: &str) -> String {
    match characteristic.value_type() {
        ValueType::Message(_) => format!("{value}.writeToBuffer()"),
        ValueType::Bare(bare) => match bare {
            Bare::U8 => format!("Uint8List.fromList([{value}])"),
            Bare::Bool => format!("Uint8List.fromList([{value} ? 1 : 0])"),
            Bare::Utf8 => format!("Uint8List.fromList(utf8.encode({value}))"),
            Bare::Bytes => value.to_string(),
            other => format!("_encode{}({value})", other.name()),
        },
        ValueType::Empty => "Uint8List(0)".to_string(),
    }
}

/// `dart format`'s line length.
const MAX_WIDTH: usize = 80;

/// One class per pipe, holding what the pipe runtime reads: the pair of
/// characteristics, the numbers it was configured with, and the two codecs.
///
/// No members are generated for a pipe characteristic itself — a chunk is not a
/// message, so a `Stream<SyncMessage>` over that characteristic would decode a
/// fragment as a message. The runtime owns those two, and this is what it needs
/// to: see `calypso-app/lib/gatt/pipe.dart` for the other half.
fn emit_pipes(out: &mut String, gatt: &Gatt, config: &Config) {
    for pipe in gatt.pipes() {
        let class = format!("{}Pipe", pascal_case(pipe.name));
        let inbound = message_of(pipe.to_device, config);
        let outbound = message_of(pipe.to_host, config);

        let _ = writeln!(
            out,
            "\n/// Pipe `{}`: `{}` in, `{}` out.\n\
             ///\n\
             /// A transfer carries one message, split into chunks of at most\n\
             /// [chunkMax] bytes and reassembled by the other end. The runtime owns\n\
             /// both characteristics; nothing here is decoded as a message except by\n\
             /// [decodeResponse] and [decodeRequest].\n\
             class {class} {{\n\
             \x20 static const String serviceUuid = '{}';\n\
             \n\
             \x20 /// `{}`: what this end writes.\n\
             \x20 static const String downUuid = '{}';\n\
             \n\
             \x20 /// `{}`: what this end subscribes to.\n\
             \x20 static const String upUuid = '{}';\n\
             \n\
             \x20 /// Bytes of payload one chunk may carry, before the frame.\n\
             \x20 static const int chunkMax = {};\n\
             \n\
             \x20 /// Largest message a transfer may carry, both ways.\n\
             \x20 static const int messageMax = {};\n\
             \n\
             \x20 /// Chunks in flight at most, before the sender waits.\n\
             \x20 static const int window = {};\n\
             \n\
             \x20 /// No-progress timeout for one transfer, in milliseconds.\n\
             \x20 static const int xferTimeoutMs = {};{codecs}\n\
             }}\n",
            pipe.name,
            inbound.as_deref().unwrap_or("raw bytes"),
            outbound.as_deref().unwrap_or("raw bytes"),
            service_uuid(gatt, pipe.to_device),
            pipe.to_device.name,
            pipe.to_device.uuid,
            pipe.to_host.name,
            pipe.to_host.uuid,
            config.pipe_chunk_max,
            config.pipe_msg_max,
            config.window,
            config.xfer_timeout_ms,
            codecs = dart_codecs(&inbound, &outbound, config),
        );
    }
}

/// The service a pipe's characteristics belong to: the validator pairs two
/// characteristics of one service.
fn service_uuid<'a>(gatt: &'a Gatt, characteristic: &Characteristic) -> &'a str {
    gatt.services
        .iter()
        .find(|service| service.proto_name == characteristic.service)
        .map(|service| service.uuid.as_str())
        .unwrap_or_default()
}

/// The message type a pipe direction carries, if it is a protobuf one.
fn message_of(characteristic: &Characteristic, config: &Config) -> Option<String> {
    match characteristic.value_type() {
        ValueType::Message(message) => Some(format!(
            "{}.{}",
            config.messages_prefix,
            short_name(message)
        )),
        _ => None,
    }
}

/// Encode and decode, per direction, so that the runtime never names a message
/// class itself: a schema change then stops at the generated file.
///
/// Each pair is a member of its own, laid out the way `dart format` leaves it: a
/// blank line before it (the class's last constant is on the line above) and one
/// between the pairs. Each direction gets a pair whether or not it carries a
/// message — a bare-bytes end encodes to itself — so neither can be empty.
fn dart_codecs(inbound: &Option<String>, outbound: &Option<String>, _config: &Config) -> String {
    let request = codec_pair("request", inbound.as_deref());
    let response = codec_pair("response", outbound.as_deref());
    format!("\n\n{request}\n\n{response}")
}

/// One direction's pair of codecs, laid out the way `dart format` leaves it: the
/// file is committed, so the repo's own `dart format --set-exit-if-changed` has to
/// pass on what the emitter writes.
fn codec_pair(what: &str, message: Option<&str>) -> String {
    let name = pascal_case(what);
    let (ty, decode) = match message {
        Some(message) => (message.to_string(), format!("{message}.fromBuffer(bytes)")),
        None => ("Uint8List".to_string(), "bytes".to_string()),
    };

    // Each line is built with a trailing space after `=>`: that space is the
    // separator when the body follows on the same line, and has to go when it does
    // not. `dart format` strips trailing whitespace, and this file is committed as
    // whatever `dart format` leaves, so the wrap has to strip it here.
    let encode_line = format!("  static Uint8List encode{name}({ty} message) => ");
    let encode = if encode_line.len() + "message.writeToBuffer();".len() <= MAX_WIDTH {
        format!("{encode_line}message.writeToBuffer();")
    } else {
        format!("{}\n      message.writeToBuffer();", encode_line.trim_end())
    };
    let decode_line = format!("  static {ty} decode{name}(Uint8List bytes) => ");
    // The trailing semicolon has to fit as well.
    let decode = if decode_line.len() + decode.len() < MAX_WIDTH {
        format!("{decode_line}{decode};")
    } else {
        format!("{}\n      {decode};", decode_line.trim_end())
    };

    // No newline of its own at either end: `dart_codecs` spaces the members out.
    format!(
        "  /// Encode a `{ty}` for a transfer.\n\
         {encode}\n\
         \n\
         \x20 /// Decode a reassembled `{ty}`.\n\
         {decode}"
    )
}

fn property_names(characteristic: &Characteristic) -> Vec<&'static str> {
    let order = [
        Prop::Read,
        Prop::Write,
        Prop::WriteNoRsp,
        Prop::Notify,
        Prop::Indicate,
    ];
    order
        .iter()
        .filter(|prop| characteristic.props.contains(prop))
        .map(|prop| match prop {
            Prop::Read => "read",
            Prop::Write => "write",
            Prop::WriteNoRsp => "write-without-response",
            Prop::Notify => "notify",
            Prop::Indicate => "indicate",
        })
        .collect()
}

fn short_name(proto_name: &str) -> &str {
    proto_name.rsplit('.').next().unwrap_or(proto_name)
}

/// `Level` -> `level`, `Rx` -> `rx`.
fn lower_camel(name: &str) -> String {
    let mut chars = name.chars();
    match chars.next() {
        Some(first) => first.to_lowercase().chain(chars).collect(),
        None => String::new(),
    }
}

fn pascal_case(name: &str) -> String {
    let mut out = String::new();
    for part in name.split(['_', '.']) {
        let mut chars = part.chars();
        if let Some(first) = chars.next() {
            out.extend(first.to_uppercase());
            out.push_str(chars.as_str());
        }
    }
    out
}
